-- ===================== Helper Functions (fn*) =====================

CREATE OR REPLACE FUNCTION __mj_BizAppsCommittees."fnAgendaItemParentAgendaItemID_GetRootID"(
    p_RecordID UUID,
    p_ParentID UUID
) RETURNS TABLE("RootID" UUID) AS $fn$
    WITH RECURSIVE cte_root_parent AS (
        SELECT
            "ID",
            "ParentAgendaItemID",
            "ID" AS root_parent_id,
            0 AS depth
        FROM __mj_BizAppsCommittees."AgendaItem"
        WHERE "ID" = COALESCE(p_ParentID, p_RecordID)

        UNION ALL

        SELECT
            c."ID",
            c."ParentAgendaItemID",
            c."ID" AS root_parent_id,
            p.depth + 1 AS depth
        FROM __mj_BizAppsCommittees."AgendaItem" c
        INNER JOIN cte_root_parent p ON c."ID" = p."ParentAgendaItemID"
        WHERE p.depth < 100
    )
    SELECT root_parent_id AS "RootID"
    FROM cte_root_parent
    WHERE "ParentAgendaItemID" IS NULL
    ORDER BY root_parent_id
    LIMIT 1;
$fn$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION __mj_BizAppsCommittees."fnCommitteeParentCommitteeID_GetRootID"(
    p_RecordID UUID,
    p_ParentID UUID
) RETURNS TABLE("RootID" UUID) AS $fn$
    WITH RECURSIVE cte_root_parent AS (
        SELECT
            "ID",
            "ParentCommitteeID",
            "ID" AS root_parent_id,
