            c."ID" AS root_parent_id,
            p.depth + 1 AS depth
        FROM __mj_BizAppsCommittees."Committee" c
        INNER JOIN cte_root_parent p ON c."ID" = p."ParentCommitteeID"
        WHERE p.depth < 100
    )
    SELECT root_parent_id AS "RootID"
    FROM cte_root_parent
    WHERE "ParentCommitteeID" IS NULL
    ORDER BY root_parent_id
    LIMIT 1;
$fn$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION __mj_BizAppsCommittees."fnCommentParentCommentID_GetRootID"(
    p_RecordID UUID,
