-- Role grants CodeGen would have added had it created the app itself
-- (newSchemaDefaults.ApplicationRoleDefaults: UI/Integration access, Developer admin)
INSERT INTO ${mjSchema}."ApplicationRole" ("ApplicationID", "RoleID", "CanAccess", "CanAdmin")
SELECT a."ID", r."ID",
       TRUE,
       CASE WHEN r."Name" = 'Developer' THEN TRUE ELSE FALSE END
FROM ${mjSchema}."Application" a
CROSS JOIN ${mjSchema}."Role" r
WHERE a."ID" IN ('B5D2C7A4-3E61-4E8B-9F2A-6C815D9E4A01', 'B5D2C7A4-3E61-4E8B-9F2A-6C815D9E4A02')
  AND r."Name" IN ('UI', 'Developer', 'Integration')
  AND NOT EXISTS (
      SELECT 1 FROM ${mjSchema}."ApplicationRole" x
      WHERE x."ApplicationID" = a."ID" AND x."RoleID" = r."ID"
  );

